'use strict';

// Independent Node test fixture, not shipped with CookWx. OpenSSL owns TLS;
// these fixed handshake bytes are deliberately not generated by the product codec.
const crypto = require('node:crypto');

function attachApplicationEcho(socket, options = {}) {
    let pending = Buffer.alloc(0);
    let ready = false;
    let rpcPending = Buffer.alloc(0);
    const rpcCancelled = new Set();
    const mode = options.mode || 'normal';
    socket.on('data', bytes => {
        if (ready) {
            if (options.onApplicationBytes) options.onApplicationBytes(bytes.length);
            if (mode === 'heartbeat') {
                rpcPending = Buffer.concat([rpcPending, bytes]);
                if (rpcPending.length > 32) return socket.destroy(new Error('Unexpected heartbeat data'));
                if (rpcPending.length < 32) return;
                const expected = Buffer.alloc(32);
                expected.write('NIF2', 0, 'ascii');
                expected.writeUInt16BE(2, 4);
                expected.writeUInt16BE(8, 6);
                expected.writeBigUInt64BE(0xfedcba9876543210n, 12);
                if (!expected.equals(rpcPending)) return socket.destroy(new Error('Invalid PONG'));
                if (options.onPong) options.onPong();
                return;
            }
            if (mode === 'rpc') {
                rpcPending = Buffer.concat([rpcPending, bytes]);
                while (rpcPending.length >= 32) {
                    const length = rpcPending.readUInt32BE(20);
                    if (length > 1048576) return socket.destroy(new Error('RPC frame too large'));
                    if (rpcPending.length < length + 32) break;
                    const frame = Buffer.from(rpcPending.subarray(0, length + 32));
                    rpcPending = rpcPending.subarray(length + 32);
                    const kind = frame.readUInt16BE(6);
                    const id = frame.readBigUInt64BE(12).toString();
                    if (kind === 6) { rpcCancelled.add(id); continue; }
                    if (kind !== 3 || length < 16 || frame.toString('ascii', 32, 36) !== 'NRP2' ||
                        frame.readUInt32BE(36) < 1 || frame.readUInt32BE(36) > 60000 ||
                        frame.readBigUInt64BE(40) !== 0n) return socket.destroy(new Error('Invalid RPC request'));
                    if (options.onRpc) options.onRpc({ id, type: frame.readUInt32BE(24), cancelled: rpcCancelled.has(id) });
                    const type = frame.readUInt32BE(24);
                    frame.writeUInt16BE(4, 6);
                    frame.writeUInt32BE(type === 902 ? 1 : 0, 36);
                    let response = frame;
                    if (type === 902) {
                        response = frame.subarray(0, 48);
                        response.writeUInt32BE(16, 20);
                    }
                    if (type === 903) response.writeUInt32BE(904, 24);
                    if (type === 901) setTimeout(() => { if (!socket.destroyed) socket.write(response); }, 120);
                    else {
                        if (!socket.write(response)) socket.pause();
                        if (type === 905) socket.write(response); // Deliberate duplicate completion.
                    }
                }
                return;
            }
            if (!socket.write(bytes)) socket.pause();
            return;
        }
        if (mode === 'silent') return;
        if (pending.length + bytes.length > 96) return socket.destroy(new Error('Business bytes before HELLO_REPLY'));
        pending = Buffer.concat([pending, bytes]);
        if (pending.length < 96) return;
        const body = pending.subarray(32);
        if (pending.toString('ascii', 0, 4) !== 'NIF2' || pending.readUInt16BE(4) !== 2 ||
            pending.readUInt16BE(6) !== 1 || pending.readUInt32BE(8) !== 0 ||
            pending.readBigUInt64BE(12) !== 0n || pending.readUInt32BE(20) !== 64 ||
            pending.readUInt32BE(24) !== 2 || pending.readUInt32BE(28) !== 0 ||
            body.toString('ascii', 0, 4) !== 'NHA2' || body.readUInt32BE(4) !== 2 ||
            !(body.readUInt32BE(8) & 1) || body.readUInt32BE(8) > 7 ||
            body.readUInt32BE(12) < 1 || body.readUInt32BE(12) > 3 ||
            body.readUInt32BE(16) < 1 || body.readUInt32BE(16) > 128 ||
            body.readUInt32BE(20) < 1024 || body.readUInt32BE(20) > 65536 ||
            body.readBigUInt64BE(56) !== 0n || !body.subarray(24, 40).some(byte => byte) ||
            !body.subarray(40, 56).some(byte => byte)) {
            return socket.destroy(new Error('Invalid application HELLO'));
        }
        if (options.onHello) options.onHello({ platform: body.readUInt32BE(12), device: body.subarray(40, 56).toString('hex') });
        const reply = Buffer.from(pending);
        reply.writeUInt16BE(2, 6);
        reply.write('NHR2', 32, 'ascii');
        reply.writeUInt32BE(body.readUInt32BE(8) & 3, 40);
        reply.writeUInt32BE(Math.min(body.readUInt32BE(16), 16), 48);
        reply.writeUInt32BE(Math.min(body.readUInt32BE(20), 4096), 52);
        crypto.randomFillSync(reply.subarray(72, 88));
        if (mode === 'wrong-nonce') reply[56] ^= 1;
        if (mode === 'early-business') reply.writeUInt16BE(5, 6);
        ready = true;
        pending = Buffer.alloc(0);
        if (!socket.write(reply)) socket.pause();
        if (mode === 'heartbeat') {
            const ping = Buffer.alloc(32);
            ping.write('NIF2', 0, 'ascii');
            ping.writeUInt16BE(2, 4);
            ping.writeUInt16BE(7, 6);
            ping.writeBigUInt64BE(0xfedcba9876543210n, 12);
            socket.write(ping);
        }
    });
    socket.on('drain', () => socket.resume());
}

module.exports = { attachApplicationEcho };